def blocks2(g):
    seen=set(); bl=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]==2 and (r,c) not in seen:
                cells=[(r,c)]; seen.add((r,c)); stack=[(r,c)]
                while stack:
                    a,b=stack.pop()
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]==2 and (x,y) not in seen:
                                seen.add((x,y)); cells.append((x,y)); stack.append((x,y))
                bl.append(cells)
    # split into 2x2 tiles per component: enumerate all 2x2 all-2 squares
    tiles=[]
    for r in range(len(g)-1):
        for c in range(len(g[0])-1):
            if g[r][c]==2 and g[r][c+1]==2 and g[r+1][c]==2 and g[r+1][c+1]==2:
                tiles.append((r,c))
    return tiles
